#!/usr/bin/env python3
# -*- coding: utf-8 -*-

# Author: Rensc
# Date: 2026-07-21
# Version: 0.2.8.18
# Function: Integrate smORF Ribo-seq evidence across multiple samples.
# Input: Long-format smORF evidence table generated by smorf_evidence.
# Output: ORF-by-sample matrix and/or integrated ORF-level evidence table.

"""Command-line entry point for multi-sample smORF evidence integration."""

from __future__ import annotations

import argparse
from argparse import Namespace
from collections.abc import Sequence

from utils.ribo.ArgsParser import args_print, file_check, now_time
from utils.smorf.smorf_riboseq_integrate import run_integration


def _build_parser() -> argparse.ArgumentParser:
    """Build the command-line argument parser."""
    parser = argparse.ArgumentParser(
        description="Integrate smORF Ribo-seq evidence across samples."
    )

    required_group = parser.add_argument_group("Required arguments")
    required_group.add_argument(
        "-i",
        "--input",
        dest="input",
        required=True,
        type=str,
        help="Long-format smORF evidence table generated by smorf_evidence.",
    )

    output_group = parser.add_argument_group("Output arguments")
    output_group.add_argument(
        "-m",
        "--output-matrix",
        dest="output_matrix",
        default=None,
        type=str,
        help="Output ORF-by-sample evidence matrix.",
    )
    output_group.add_argument(
        "-o",
        "--output-integrated",
        dest="output_integrated",
        default=None,
        type=str,
        help="Output integrated ORF-level evidence table.",
    )

    integration_group = parser.add_argument_group("Integration arguments")
    integration_group.add_argument(
        "-c",
        "--capture-labels",
        dest="capture_labels",
        default="LowConfidence,MediumConfidence,HighConfidence",
        type=str,
        help="Evidence labels defining captured samples.",
    )
    integration_group.add_argument(
        "-p",
        "--pass-labels",
        dest="pass_labels",
        default="MediumConfidence,HighConfidence",
        type=str,
        help="Evidence labels defining reliable samples.",
    )
    integration_group.add_argument(
        "-n",
        "--excellent-min-samples",
        dest="excellent_min_samples",
        default=2,
        type=int,
        help="Minimum reliable samples required for Excellent evidence.",
    )

    return parser


def _validate_args(args: Namespace) -> None:
    """Validate command-line arguments."""
    file_check(args.input)
    if not args.output_matrix and not args.output_integrated:
        raise ValueError(
            "At least one of --output-matrix or --output-integrated is required."
        )
    if args.excellent_min_samples < 1:
        raise ValueError("--excellent-min-samples must be >= 1.")


def _parse_args(argv: Sequence[str] | None = None) -> Namespace:
    """Parse, validate, and print command-line arguments."""
    parser = _build_parser()
    args = parser.parse_args(argv)
    _validate_args(args)
    args_print(args)
    return args


def _print_step(step: int, message: str) -> None:
    """Print a standardized pipeline step message."""
    print(f"\nStep{step}: {message}", flush=True)


def _run_integration_pipeline(args: Namespace) -> None:
    """Run multi-sample smORF evidence integration."""
    _print_step(2, "Integrate smORF evidence across samples.")
    run_integration(args)


def main(argv: Sequence[str] | None = None) -> None:
    """Command-line entry point for smorf_integrate."""
    now_time()
    print("\nIntegrate smORF Ribo-seq evidence tables.", flush=True)
    _print_step(1, "Checking the input arguments.")

    args = _parse_args(argv)
    _run_integration_pipeline(args)

    print("\nAll done.", flush=True)
    now_time()


if __name__ == "__main__":
    main()
